// Browser voices expose names/locales, not a reliable gender field. Prefer known female English voices.
export function femaleEnglishVoice(voices=[]){const english=voices.filter(v=>/^en(?:[-_]|$)/i.test(v.lang));const female=/samantha|flo|sandy|shelley|grandma|martha|serena|karen|moira|tessa|victoria|aria|jenny|sonia|libby|hazel|susan|zira|ava|emma|allison|joanna|salli|kendra|kimberly|female|google (?:us|uk) english(?! male)/i,knownMale=/\b(?:daniel|alex|david|george|mark|james|ryan|guy|aaron|fred|oliver|male)\b/i;return english.filter(v=>female.test(v.name)&&!knownMale.test(v.name)).sort((a,b)=>Number(b.localService)-Number(a.localService)||Number(/^en-GB/i.test(b.lang))-Number(/^en-GB/i.test(a.lang)))[0]||null;}
export function supplyWords(text){const m=/^please\s+(?:bring|select(?:\s+the word cards for)?)\s+(.+?)[.!]?$/i.exec(String(text).trim());return m?m[1].split(/,\s*|\s+and\s+/).map(w=>w.trim()).filter(Boolean):null;}
export function spokenRequest(text){const words=supplyWords(text);return words?`Please select ${words.length>1?words.slice(0,-1).join(', ')+' and '+words.at(-1):words[0]}.`:String(text);}
